import{_ as i,J as o,b as r,e as t,a8 as n,f as l,L as p}from"./chunks/framework.CumEd6mW.js";const h=JSON.parse('{"title":"GR32_LowLevel","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_LowLevel","entity":"GR32_LowLevel","kind":"Unit","summary":"Provides low-level memory operations, fast mathematical routines, bit manipulations, coordinate wrapping, and optimized rounding operations.","title":"GR32_LowLevel","date":1788949297000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_LowLevel/index.md","filePath":"api/GR32_LowLevel/index.md","lastUpdated":1788949297000,"timestamp":1788949297000,"datetime":"2026-09-09T10:21:37.000Z"}'),s={name:"api/GR32_LowLevel/index.md"};function c(L,e,d,w,v,f){const a=o("ApiMembers");return r(),t("div",null,[e[0]||(e[0]=n('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_LowLevel</code> unit contains performance-critical low-level primitives used extensively across Graphics32. It provides optimized memory fills and copies, fast division, fast arithmetic shifts, range clamping and wrapping functions, and accelerated fast-rounding routines (utilizing CPU instruction set extensions such as SSE2 and SSE4.1 where available).</p><p>Key capabilities provided by this unit include:</p><ul><li><strong>Optimized Memory Operations</strong>: 32-bit and 16-bit array filling and copying routines (<a href="/api/GR32_LowLevel/FillLongword">FillLongword</a>, <a href="/api/GR32_LowLevel/FillWord">FillWord</a>, <a href="/api/GR32_LowLevel/MoveLongword">MoveLongword</a>, <a href="/api/GR32_LowLevel/MoveWord">MoveWord</a>).</li><li><strong>Stack Memory Allocation</strong>: Stack-based dynamic memory allocation primitives (<a href="/api/GR32_LowLevel/StackAlloc">StackAlloc</a>, <a href="/api/GR32_LowLevel/StackAlloc">StackFree</a>).</li><li><strong>Fast Value Manipulation</strong>: Swapping operations (<a href="/api/GR32_LowLevel/Swap">Swap</a>, <a href="/api/GR32_LowLevel/Swap">Swap32</a>, <a href="/api/GR32_LowLevel/Swap16">Swap16</a>, <a href="/api/GR32_LowLevel/Swap16">Swap64</a>), conditional swapping (<a href="/api/GR32_LowLevel/TestSwap">TestSwap</a>), and range clipping check (<a href="/api/GR32_LowLevel/TestClip">TestClip</a>).</li><li><strong>Boundary Clamping, Wrapping &amp; Reflection</strong>: Flexible coordinate mapping functions including <a href="/api/GR32_LowLevel/Clamp">Clamp</a>, <a href="/api/GR32_LowLevel/Constrain">Constrain</a>, <a href="/api/GR32_LowLevel/SwapConstrain">SwapConstrain</a>, <a href="/api/GR32_LowLevel/Wrap">Wrap</a>, <a href="/api/GR32_LowLevel/WrapMem">WrapMem</a>, <a href="/api/GR32_LowLevel/WrapPow2">WrapPow2</a>, <a href="/api/GR32_LowLevel/Mirror">Mirror</a>, <a href="/api/GR32_LowLevel/Reflect">Reflect</a>, and <a href="/api/GR32_LowLevel/ReflectPow2">ReflectPow2</a>.</li><li><strong>Optimal Wrap Function Resolvers</strong>: <a href="/api/GR32_LowLevel/GetOptimalWrap">GetOptimalWrap</a>, <a href="/api/GR32_LowLevel/GetOptimalReflect">GetOptimalReflect</a>, <a href="/api/GR32_LowLevel/GetWrapProc">GetWrapProc</a>, and <a href="/api/GR32_LowLevel/GetWrapProcEx">GetWrapProcEx</a> for dynamically selecting optimized wrapping procedure delegates.</li><li><strong>Fast Integer Division</strong>: Accelerated division by 255 and 127 (<a href="/api/GR32_LowLevel/Div255">Div255</a>, <a href="/api/GR32_LowLevel/Div255">FastDiv255</a>, <a href="/api/GR32_LowLevel/Div255">Div255Round</a>, <a href="/api/GR32_LowLevel/Div127">Div127</a>).</li><li><strong>Fast Rounding Functions</strong>: High-performance replacement for RTL rounding and truncation routines (<a href="/api/GR32_LowLevel/Fast Rounding Functions">FastFloor, FastCeil, FastTrunc, FastRound</a>).</li><li><strong>Arithmetic Right Shifts</strong>: Sign-preserving bitwise right shifts (<a href="/api/GR32_LowLevel/SAR">SAR_3</a> through <a href="/api/GR32_LowLevel/SAR">SAR_16</a>).</li><li><strong>Color Processing</strong>: Color format conversion between VCL/WinAPI <code>TColor</code> and 32-bit <code>TColor32</code> via <a href="/api/GR32_LowLevel/ColorSwap">ColorSwap</a>.</li></ul><hr>',5)),l("p",null,[p(a,{type:"members"})])])}const R=i(s,[["render",c]]);export{h as __pageData,R as default};
